+		want HookHost
+	}{
+		{
+			name: "copilot cli numeric timestamp",
+			raw:  `{"timestamp":1771480081360,"sessionId":"sess-123","prompt":"hi"}`,
+			want: HostCopilotCLI,
+		},
+		{
+			name: "vscode hook event field",
